'use client';
import Link from 'next/link';
import { useState } from 'react';
import { ApiError, api, uploadLessonMedia } from '@/lib/api';
import { ErrorBox, Loading, useApp, useAsync } from '@/components/app/AppShell';
import { useI18n } from '@/components/Providers';

interface Rec { id: string; code: string | null; data: Record<string, any> }

/** Learn: build a course in one place — lessons (video / text / file link), exams and their questions — then publish. The server still enforces every rule (a course needs a lesson to be published). */
export default function CourseBuilder() {
  const app = useApp(); const { locale } = useI18n(); const t = (ar: string, en: string) => (locale === 'ar' ? ar : en);
  const [cid, setCid] = useState(''); const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null); const [busy, setBusy] = useState(false);
  const courses = useAsync(() => api<Rec[]>('/tenant/p/course?pageSize=100&sort=createdAt&dir=desc').then((r) => r.data), []);
  const lessons = useAsync(() => (cid ? api<Rec[]>(`/tenant/p/lesson?courseId=${cid}&pageSize=100&sort=position&dir=asc`).then((r) => r.data) : Promise.resolve([] as Rec[])), [cid]);
  const exams = useAsync(() => (cid ? api<Rec[]>(`/tenant/p/exam?courseId=${cid}&pageSize=50`).then((r) => r.data) : Promise.resolve([] as Rec[])), [cid]);
  const [pct, setPct] = useState<Record<string, number>>({}); const [exId, setExId] = useState(''); const questions = useAsync(() => (exId ? api<Rec[]>(`/tenant/p/question?examId=${exId}&pageSize=100`).then((r) => r.data) : Promise.resolve([] as Rec[])), [exId]);
  const [lf, setLf] = useState({ title: '', kind: 'video', contentUrl: '', durationMin: '', isPreview: false }); const [ef, setEf] = useState({ title: '', passScore: '60', maxAttempts: '3' }); const [qf, setQf] = useState({ text: '', options: '', correct: '1', points: '1' });
  if (!app.can('courses.read')) return <div className="alert warn" role="alert">{t('لا تملك صلاحية عرض الكورسات.', 'You cannot view courses.')}</div>;
  if (courses.error) return <ErrorBox error={courses.error} retry={courses.reload} />; if (!courses.data) return <Loading />;
  const course = courses.data.find((c) => c.id === cid); const L = lessons.data ?? []; const nextPos = L.reduce((a, l) => Math.max(a, Number(l.data.position)), 0) + 1;
  const run = async (fn: () => Promise<unknown>, ok: string, after: () => void) => { setBusy(true); setMsg(null); try { await fn(); setMsg({ ok: true, text: ok }); after(); } catch (e) { const a = e as ApiError; setMsg({ ok: false, text: a.message + (a.fields ? ' — ' + Object.entries(a.fields).map(([k, v]) => `${k}: ${v.join(', ')}`).join('; ') : '') }); } finally { setBusy(false); } };
  const addLesson = () => run(() => api('/tenant/p/lesson', { method: 'POST', body: { courseId: cid, position: nextPos, title: lf.title.trim(), kind: lf.kind, ...(lf.contentUrl ? { contentUrl: lf.contentUrl.trim() } : {}), ...(lf.durationMin ? { durationMin: Number(lf.durationMin) } : {}), isPreview: lf.isPreview } }), t('تمت إضافة الدرس.', 'Lesson added.'), () => { setLf({ title: '', kind: 'video', contentUrl: '', durationMin: '', isPreview: false }); lessons.reload(); });
  const setStatus = (status: string) => run(() => api(`/tenant/p/course/${cid}`, { method: 'PATCH', body: { status } }), t('تم تحديث حالة الكورس.', 'Course status updated.'), () => courses.reload());
  const addExam = () => run(() => api('/tenant/p/exam', { method: 'POST', body: { courseId: cid, title: ef.title.trim(), passScore: Number(ef.passScore), maxAttempts: Number(ef.maxAttempts) } }), t('تمت إضافة الاختبار.', 'Exam added.'), () => { setEf({ title: '', passScore: '60', maxAttempts: '3' }); exams.reload(); });
  const opts = qf.options.split('\n').map((x) => x.trim()).filter(Boolean);
  const addQuestion = () => run(() => api('/tenant/p/question', { method: 'POST', body: { examId: exId, text: qf.text.trim(), options: opts.map((text) => ({ text })), correctIndex: Number(qf.correct) - 1, points: Number(qf.points) } }), t('تمت إضافة السؤال.', 'Question added.'), () => { setQf({ text: '', options: '', correct: '1', points: '1' }); questions.reload(); });
  return (
    <>
      <div className="row between"><h1 style={{ fontSize: '1.6rem', margin: 0 }}>{t('بناء الكورس', 'Course builder')}</h1>{app.can('courses.create') && <Link className="btn" href="/app/e/course/new">{t('كورس جديد', 'New course')}</Link>}</div>
      {msg && <div className={`alert ${msg.ok ? 'ok' : 'error'}`} role="alert">{msg.text}</div>}
      <label className="field">{t('اختر الكورس', 'Choose a course')}<select value={cid} onChange={(e) => { setCid(e.target.value); setExId(''); setMsg(null); }}><option value="">—</option>{courses.data.map((c) => <option key={c.id} value={c.id}>{c.data.title} ({c.data.status})</option>)}</select></label>
      {!courses.data.length && <p className="muted">{t('أنشئ أول كورس ثم عُد هنا لإضافة الدروس والاختبارات.', 'Create your first course, then come back to add lessons and exams.')}</p>}
      {course && <>
        <section className="card stack"><div className="row between"><div><h3 style={{ margin: 0 }}>{course.data.title}</h3><span className="small muted">{course.code} · ★ {course.data.ratingCount ? (Number(course.data.ratingAvg100) / 100).toFixed(1) : '—'} ({course.data.ratingCount ?? 0})</span></div>
          <div className="row"><span className={`badge ${course.data.status === 'published' ? 'ok' : 'warn'}`}>{course.data.status}</span>{app.can('courses.update') && (course.data.status === 'published' ? <button className="btn sm" disabled={busy} onClick={() => setStatus('archived')}>{t('أرشفة', 'Archive')}</button> : <button className="btn primary sm" disabled={busy} onClick={() => setStatus('published')}>{t('نشر', 'Publish')}</button>)}<Link className="btn sm" href={`/app/e/course/${cid}`}>{t('بيانات الكورس', 'Course details')}</Link></div></div></section>
        <section className="card stack"><h3>{t('الدروس', 'Lessons')} <span className="badge">{L.length}</span></h3>
          {lessons.error ? <ErrorBox error={lessons.error} retry={lessons.reload} /> : !lessons.data ? <Loading /> : !L.length ? <p className="muted">{t('لا توجد دروس. أضف الدرس الأول ليمكن نشر الكورس.', 'No lessons yet. Add the first one so the course can be published.')}</p> :
            <div className="table-wrap"><table><thead><tr><th scope="col">#</th><th scope="col">{t('الدرس', 'Lesson')}</th><th scope="col">{t('النوع', 'Type')}</th><th scope="col">{t('المدة', 'Min')}</th><th scope="col">{t('معاينة', 'Preview')}</th><th /></tr></thead><tbody>{L.map((l) => <tr key={l.id}><td>{l.data.position}</td><td>{l.data.title}{l.data.contentUrl && <div className="mono small muted" style={{ overflowWrap: 'anywhere' }}>{String(l.data.contentUrl)}</div>}{l.data.fileId && <div className="small" data-testid="lesson-file-attached">✔ {t('ملف مرفوع', 'File uploaded')}</div>}
            {app.can('lessons.update') && l.data.kind !== 'text' && <label className="field small" style={{ marginTop: 4 }}>{l.data.kind === 'video' ? t('رفع فيديو (MP4 / WebM حتى 150 ميجا)', 'Upload video (MP4 / WebM, up to 150 MB)') : t('رفع ملف للتحميل (PDF / مستند حتى 10 ميجا)', 'Upload downloadable file (PDF / document, up to 10 MB)')}
              <input type="file" accept={l.data.kind === 'video' ? 'video/mp4,video/webm' : '.pdf,.docx,.xlsx,.pptx,.txt,.csv,image/*'} disabled={busy}
                onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ''; if (!f) return; void run(async () => { const up = await uploadLessonMedia(l.data.kind === 'video' ? 'video' : 'material', l.id, f, (v) => setPct((x) => ({ ...x, [l.id]: v }))); await api(`/tenant/p/lesson/${l.id}`, { method: 'PATCH', body: { fileId: up.id } }); setPct((x) => { const n = { ...x }; delete n[l.id]; return n; }); }, t('تم رفع الملف وربطه بالدرس.', 'File uploaded and attached to the lesson.'), lessons.reload); }} />
              {pct[l.id] !== undefined && <progress max={100} value={pct[l.id]} aria-label={t('تقدم الرفع', 'Upload progress')} />}</label>}</td><td>{l.data.kind}</td><td>{l.data.durationMin ?? ''}</td><td>{l.data.isPreview ? '✓' : ''}</td><td className="row"><Link className="btn sm" href={`/app/e/lesson/${l.id}`}>{t('تعديل', 'Edit')}</Link></td></tr>)}</tbody></table></div>}
          {app.can('lessons.create') && <div className="grid g4"><label className="field">{t('عنوان الدرس', 'Lesson title')}<input maxLength={200} value={lf.title} onChange={(e) => setLf({ ...lf, title: e.target.value })} /></label><label className="field">{t('النوع', 'Type')}<select value={lf.kind} onChange={(e) => setLf({ ...lf, kind: e.target.value })}><option value="video">video</option><option value="text">text</option><option value="file">file</option></select></label>
            <label className="field">{t('رابط المحتوى (فيديو مستضاف خارجيًا)', 'Content URL (externally hosted video)')}<input className="ltr" inputMode="url" placeholder="https://" value={lf.contentUrl} onChange={(e) => setLf({ ...lf, contentUrl: e.target.value })} /></label><label className="field">{t('المدة بالدقائق', 'Minutes')}<input type="number" min={0} max={1440} value={lf.durationMin} onChange={(e) => setLf({ ...lf, durationMin: e.target.value })} /></label>
            <label className="row"><input type="checkbox" checked={lf.isPreview} onChange={(e) => setLf({ ...lf, isPreview: e.target.checked })} />{t('متاح كمعاينة مجانية', 'Free preview')}</label><div><button className="btn primary" disabled={busy || !lf.title.trim()} onClick={addLesson}>{t('إضافة الدرس', 'Add lesson')} #{nextPos}</button></div></div>}</section>
        <section className="card stack"><h3>{t('الاختبارات', 'Exams')} <span className="badge">{exams.data?.length ?? 0}</span></h3>
          {(exams.data ?? []).map((x) => <div key={x.id} className="card flat row between"><span><b>{x.data.title}</b> <span className="small muted">{t('النجاح', 'Pass')} {x.data.passScore}% · {x.data.maxAttempts} {t('محاولات', 'attempts')}</span></span><button className={`btn sm ${exId === x.id ? 'primary' : ''}`} onClick={() => setExId(exId === x.id ? '' : x.id)}>{t('الأسئلة', 'Questions')}</button></div>)}
          {app.can('exams.create') && <div className="grid g4"><label className="field">{t('عنوان الاختبار', 'Exam title')}<input value={ef.title} onChange={(e) => setEf({ ...ef, title: e.target.value })} /></label><label className="field">{t('درجة النجاح %', 'Pass %')}<input type="number" min={1} max={100} value={ef.passScore} onChange={(e) => setEf({ ...ef, passScore: e.target.value })} /></label><label className="field">{t('عدد المحاولات', 'Max attempts')}<input type="number" min={1} max={20} value={ef.maxAttempts} onChange={(e) => setEf({ ...ef, maxAttempts: e.target.value })} /></label><div style={{ alignSelf: 'end' }}><button className="btn primary" disabled={busy || !ef.title.trim()} onClick={addExam}>{t('إضافة اختبار', 'Add exam')}</button></div></div>}</section>
        {exId && <section className="card stack"><h3>{t('أسئلة الاختبار', 'Exam questions')} <span className="badge">{questions.data?.length ?? 0}</span></h3>
          {(questions.data ?? []).map((q, i) => <div key={q.id} className="card flat"><b>{i + 1}. {q.data.text}</b><ol style={{ margin: '6px 0 0', paddingInlineStart: 22 }}>{((q.data.options as { text: string }[]) ?? []).map((o, k) => <li key={k} style={k === Number(q.data.correctIndex) ? { fontWeight: 700 } : undefined}>{o.text}{k === Number(q.data.correctIndex) ? ' ✓' : ''}</li>)}</ol></div>)}
          {app.can('questions.create') && <div className="stack"><label className="field">{t('نص السؤال', 'Question')}<textarea rows={2} value={qf.text} onChange={(e) => setQf({ ...qf, text: e.target.value })} /></label>
            <label className="field">{t('الاختيارات (كل اختيار في سطر، من 2 إلى 6)', 'Options (one per line, 2–6)')}<textarea rows={4} value={qf.options} onChange={(e) => setQf({ ...qf, options: e.target.value })} /></label>
            <div className="grid g4"><label className="field">{t('رقم الإجابة الصحيحة', 'Correct option #')}<input type="number" min={1} max={Math.max(2, opts.length)} value={qf.correct} onChange={(e) => setQf({ ...qf, correct: e.target.value })} /></label><label className="field">{t('الدرجة', 'Points')}<input type="number" min={1} max={100} value={qf.points} onChange={(e) => setQf({ ...qf, points: e.target.value })} /></label>
              <div style={{ alignSelf: 'end' }}><button className="btn primary" disabled={busy || !qf.text.trim() || opts.length < 2 || opts.length > 6 || Number(qf.correct) < 1 || Number(qf.correct) > opts.length} onClick={addQuestion}>{t('إضافة سؤال', 'Add question')}</button></div></div></div>}</section>}
      </>}
    </>
  );
}
